<script lang="ts">
  /**
   * App Component
   *
   * Main application layout for the Singing Trainer.
   */
  import { onMount, onDestroy } from 'svelte';
  import {
    SingingCanvas,
    DroneControls,
    StartButton,
    MicInputSelector,
    PitchHighlightToggle,
    ThemeSettings,
    LyricLabelControls,
    PitchReadout,
    RangeControl,
    ExerciseControls,
    UltrastarControls,
    SpeakingPitchPanel,
    DifficultySettings,
    OverdubBuilderToolbar,
  } from './lib/components/index.js';
  import { ResultsModal } from './lib/components/feedback/index.js';
  import { ExerciseChooserModal, OverdubExerciseChooserModal } from './lib/components/chooser/index.js';
  import { overdubExerciseState } from './lib/stores/overdubExerciseState.svelte.js';
  import { CalibrationWizard } from './lib/calibration/index.js';
  import { handoffState } from './lib/stores/handoffState.svelte.js';
  import { appState } from './lib/stores/appState.svelte.js';
  import { highwayState } from './lib/stores/highwayState.svelte.js';
  import { ultrastarState } from './lib/stores/ultrastarState.svelte.js';
  import { resultsState } from './lib/stores/resultsState.svelte.js';
  import { exerciseState } from './lib/stores/exerciseState.svelte.js';
  import { overdubState } from './lib/stores/overdubState.svelte.js';
  import { startDetection, stopDetection } from './lib/services/pitchDetection.js';
  import { registerTemplates, ALL_LESSONS } from '@mlt/lesson-templates';

  // Calibration wizard state
  let showCalibrationWizard = $state(false);

  // Accordion state: only one sidebar section open at a time
  let openSection: number | null = $state(null);

  function handleToggle(index: number) {
    return (event: Event & { currentTarget: EventTarget & HTMLDetailsElement }) => {
      if (event.currentTarget.open) {
        openSection = index;
      } else if (openSection === index) {
        openSection = null;
      }
    };
  }

  // Exercise Controls component reference
  let exerciseControlsRef: { handleLessonStart: (lessonId: string, settings: Record<string, number | boolean>) => void } | undefined;

  function openCalibrationWizard() {
    showCalibrationWizard = true;
  }

  function handleCalibrationComplete() {
    showCalibrationWizard = false;
  }

  function handleCalibrationCancel() {
    showCalibrationWizard = false;
  }

  // Reactive state for Ultrastar
  const isUltrastarActive = $derived(ultrastarState.state.isActive);
  const showOverdubBuilderToolbar = $derived(
    openSection === 5 || overdubExerciseState.state.isActive
  );

  // Register performance complete callbacks
  $effect(() => {
    // Register highway completion callback
    const unsubscribe = highwayState.onPerformanceComplete((results) => {
      // Check if this is an Ultrastar song
      if (ultrastarState.state.isActive && ultrastarState.state.isPlaying) {
        const summary = resultsState.calculateSummary(
          results,
          ultrastarState.state.targetNotes
        );
        resultsState.show(summary, {
          title: ultrastarState.title,
          artist: ultrastarState.artist,
          source: 'ultrastar',
        });
        ultrastarState.setPlaying(false);
      }
      // Exercises handle their own results display
    });

    return unsubscribe;
  });

  // Handle results modal retry
  function handleResultsRetry() {
    if (resultsState.state.source === 'ultrastar') {
      // Restart Ultrastar song
      highwayState.reset();
      highwayState.setTargetNotes(ultrastarState.state.targetNotes);
      appState.setVisualizationMode('highway');
    } else if (resultsState.state.source === 'exercise') {
      // Reset highway and request restart - ExerciseControls will auto-start
      highwayState.reset();
      exerciseState.reset();
      exerciseState.requestRestart();
    }
  }

  // Handle results modal close
  function handleResultsClose() {
    // Clear highway and reset to clean state
    highwayState.reset();
    if (resultsState.state.source === 'exercise') {
      exerciseState.reset();
    }
  }

  // Check for handoff on mount
  onMount(async () => {
    // Register lesson templates
    try {
      registerTemplates(ALL_LESSONS);
    } catch {
      // Templates might already be registered.
    }

    const wasHandoff = await handoffState.checkAndConsumeHandoff();

    if (wasHandoff) {
      // Update the pitch range based on imported data
      const suggestedRange = handoffState.suggestedPitchRange;
      if (suggestedRange) {
        appState.setYAxisRange(suggestedRange);
      }
    }

    // Auto-start microphone pitch detection by default on app startup.
    try {
      await startDetection();
      appState.setDetecting(true);
    } catch (error) {
      appState.setDetecting(false);
      console.warn('[App] Auto-start mic detection failed; user can start manually.', error);
    }
  });

  // Clean up on unmount
  onDestroy(() => {
    stopDetection();
    void overdubState.dispose();
  });

  // Reactive state
  const hasImportedSnapshot = $derived(handoffState.state.hasImportedSnapshot);
  const transposition = $derived(handoffState.state.transpositionSemitones);
  const handoffError = $derived(handoffState.state.error);

  function handleBringBack() {
    handoffState.bringBackToStudentNotation();
  }

  function handleTransposeUp() {
    handoffState.transposeUp();
  }

  function handleTransposeDown() {
    handoffState.transposeDown();
  }

  /**
   * Handle starting a lesson from the chooser modal
   */
  function handleLessonStart(lessonId: string, settings: Record<string, number | boolean>) {
    exerciseControlsRef?.handleLessonStart(lessonId, settings);
  }

  /**
   * Handle starting an overdub exercise from the exercise chooser modal
   */
  function handleExerciseStart(exerciseId: string, settings: Record<string, number | boolean>) {
    overdubExerciseState.loadExercise(exerciseId, settings);
  }
</script>

<div class="app">
  {#if handoffError}
    <div class="error-banner">
      {handoffError}
    </div>
  {/if}

  <main class="main">
    <aside class="sidebar sidebar--left">
      <div class="sidebar-header">
        <h1 class="sidebar-title">Singing Trainer</h1>
        {#if hasImportedSnapshot}
          <div class="handoff-controls">
            <div class="transposition-control">
              <button class="transpose-btn" onclick={handleTransposeDown} title="Transpose down">-</button>
              <span class="transposition-label">
                {transposition >= 0 ? '+' : ''}{transposition}
              </span>
              <button class="transpose-btn" onclick={handleTransposeUp} title="Transpose up">+</button>
            </div>
            <button class="bring-back-btn" onclick={handleBringBack}>
              Bring Back to Student Notation
            </button>
          </div>
        {/if}
      </div>

      <details class="settings-details" open={openSection === 0} ontoggle={handleToggle(0)}>
        <summary class="settings-summary">Mic Settings</summary>
        <div class="settings-content">
          <StartButton />
          <MicInputSelector />
          <PitchReadout />
        </div>
      </details>

      <details class="settings-details" open={openSection === 1} ontoggle={handleToggle(1)}>
        <summary class="settings-summary">Theme Settings</summary>
        <div class="settings-content">
          <ThemeSettings />
          <PitchHighlightToggle />
        </div>
      </details>

      <details class="settings-details" open={openSection === 2} ontoggle={handleToggle(2)}>
        <summary class="settings-summary">User Settings</summary>
        <div class="settings-content">
          <SpeakingPitchPanel onCalibrate={openCalibrationWizard} />
          <RangeControl />
        </div>
      </details>

      <details class="settings-details" open={openSection === 3} ontoggle={handleToggle(3)}>
        <summary class="settings-summary">Drone Controls</summary>
        <div class="settings-content">
          <DroneControls />
        </div>
      </details>

      <details class="settings-details" open={openSection === 4} ontoggle={handleToggle(4)}>
        <summary class="settings-summary">Difficulty Settings</summary>
        <div class="settings-content">
          <DifficultySettings />
        </div>
      </details>

      <details class="settings-details" open={openSection === 5} ontoggle={handleToggle(5)}>
        <summary class="settings-summary">Overdub Builder</summary>
        <div class="settings-content">
          <p class="builder-toolbar-hint">
            Builder controls are in the bottom toolbar.
          </p>
          <p class="builder-toolbar-hint builder-toolbar-hint--subtle">
            Keep this section open to pin the toolbar while not in an exercise.
          </p>
        </div>
      </details>

      <details class="settings-details" open={openSection === 6} ontoggle={handleToggle(6)}>
        <summary class="settings-summary">Exercises &amp; Lessons</summary>
        <div class="settings-content">
          <ExerciseControls bind:this={exerciseControlsRef} />
        </div>
      </details>

      <details class="settings-details" open={openSection === 7} ontoggle={handleToggle(7)}>
        <summary class="settings-summary">UltraStar Karaoke</summary>
        <div class="settings-content">
          <UltrastarControls />
          <LyricLabelControls />
        </div>
      </details>

      {#if hasImportedSnapshot}
        <div class="control-group">
          <h3 class="control-group-title">Imported Material</h3>
          <div class="import-info">
            <span class="import-label">Voices:</span>
            <span class="import-value">{handoffState.voices.length}</span>
          </div>
          <div class="import-info">
            <span class="import-label">Tempo:</span>
            <span class="import-value">{handoffState.tempo} BPM</span>
          </div>
          {#if handoffState.timeGrid}
            <div class="import-info">
              <span class="import-label">Microbeats:</span>
              <span class="import-value">{handoffState.timeGrid.microbeatCount}</span>
            </div>
          {/if}
        </div>
      {/if}
    </aside>

    <section class="canvas-area">
      <div class="canvas-main">
        <SingingCanvas />
      </div>
      <OverdubBuilderToolbar visible={showOverdubBuilderToolbar} />
    </section>
  </main>

  <!-- Avatar mount point for lesson instructions -->
  <div id="lesson-avatar-mount" class="avatar-mount"></div>

  <!-- Lesson Chooser Modal -->
  <ExerciseChooserModal onstart={handleLessonStart} />

  <!-- Overdub Exercise Chooser Modal -->
  <OverdubExerciseChooserModal onstart={handleExerciseStart} />

  <!-- Results Modal -->
  <ResultsModal onRetry={handleResultsRetry} onClose={handleResultsClose} />

  <!-- Calibration Wizard Modal -->
  {#if showCalibrationWizard}
    <CalibrationWizard
      onComplete={handleCalibrationComplete}
      onCancel={handleCalibrationCancel}
    />
  {/if}
</div>

<style>
  .app {
    display: flex;
    flex-direction: column;
    height: 100%;
    width: 100%;
  }

  .main {
    display: flex;
    flex: 1;
    overflow: hidden;
  }

  .sidebar {
    display: flex;
    flex-direction: column;
    gap: var(--spacing-lg);
    padding: var(--spacing-lg);
    background-color: var(--color-bg-light);
    border-right: 1px solid rgba(255, 255, 255, 0.1);
    min-width: 260px;
    max-width: 300px;
    overflow-y: auto; /* Allow vertical scrolling */
  }

  .sidebar-header {
    display: flex;
    flex-direction: column;
    gap: var(--spacing-sm);
  }

  .sidebar-title {
    margin: 0;
    font-size: var(--font-size-xl);
    font-weight: 700;
    color: var(--color-text);
    line-height: 1.1;
  }

  .control-group {
    display: flex;
    flex-direction: column;
    gap: var(--spacing-md);
  }

  .control-group-title {
    font-size: var(--font-size-sm);
    font-weight: 600;
    color: var(--color-text-muted);
    text-transform: uppercase;
    letter-spacing: 0.05em;
    margin: 0;
  }

  .canvas-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: var(--spacing-sm);
    padding: var(--spacing-lg);
    overflow: hidden;
    min-width: 0;
    min-height: 0;
  }

  .canvas-main {
    flex: 1;
    min-width: 0;
    min-height: 0;
    display: flex;
  }

  /* Handoff controls */
  .handoff-controls {
    display: flex;
    flex-direction: column;
    align-items: stretch;
    gap: var(--spacing-sm);
  }

  .transposition-control {
    display: flex;
    align-items: center;
    gap: var(--spacing-xs);
    background-color: var(--color-bg);
    border-radius: var(--radius-md);
    padding: var(--spacing-xs) var(--spacing-sm);
  }

  .transpose-btn {
    width: 28px;
    height: 28px;
    border: none;
    border-radius: var(--radius-sm);
    background-color: var(--color-bg-light);
    color: var(--color-text);
    font-size: var(--font-size-lg);
    font-weight: 600;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: background-color 0.15s ease;
  }

  .transpose-btn:hover {
    background-color: var(--color-primary);
    color: white;
  }

  .transposition-label {
    font-size: var(--font-size-sm);
    font-weight: 600;
    color: var(--color-text);
    min-width: 32px;
    text-align: center;
  }

  .bring-back-btn {
    padding: var(--spacing-sm) var(--spacing-md);
    border: none;
    border-radius: var(--radius-md);
    background-color: var(--color-primary);
    color: white;
    font-size: var(--font-size-sm);
    font-weight: 600;
    cursor: pointer;
    transition: background-color 0.15s ease;
    width: 100%;
  }

  .bring-back-btn:hover {
    background-color: var(--color-primary-dark, #4a7bc8);
  }

  /* Error banner */
  .error-banner {
    background-color: var(--color-error, #dc3545);
    color: white;
    padding: var(--spacing-sm) var(--spacing-lg);
    text-align: center;
    font-size: var(--font-size-sm);
  }

  /* Import info */
  .import-info {
    display: flex;
    justify-content: space-between;
    font-size: var(--font-size-sm);
    padding: var(--spacing-xs) 0;
  }

  .import-label {
    color: var(--color-text-muted);
  }

  .import-value {
    color: var(--color-text);
    font-weight: 600;
  }

  /* Settings dropdown */
  .settings-details {
    background-color: var(--color-surface, rgba(255, 255, 255, 0.05));
    border-radius: var(--radius-sm);
    padding: var(--spacing-xs);
    width: 100%;
  }

  .settings-summary {
    cursor: pointer;
    font-size: var(--font-size-sm);
    font-weight: 600;
    color: var(--color-text-muted);
    text-transform: uppercase;
    letter-spacing: 0.05em;
    padding: var(--spacing-xs);
    user-select: none;
    list-style: none;
  }

  .settings-summary::-webkit-details-marker {
    display: none;
  }

  .settings-summary::before {
    content: '▶';
    display: inline-block;
    margin-right: var(--spacing-xs);
    font-size: 0.7em;
    transition: transform 0.2s ease;
  }

  .settings-details[open] .settings-summary::before {
    transform: rotate(90deg);
  }

  .settings-summary:hover {
    color: var(--color-primary);
  }

  .settings-content {
    display: flex;
    flex-direction: column;
    gap: var(--spacing-md);
    padding: var(--spacing-sm);
    padding-top: var(--spacing-md);
    width: 100%;
  }

  .builder-toolbar-hint {
    margin: 0;
    font-size: var(--font-size-sm);
    color: var(--color-text);
    line-height: 1.35;
  }

  .builder-toolbar-hint--subtle {
    color: var(--color-text-muted);
    font-size: var(--font-size-xs);
  }

  @media (max-width: 900px) {
    .main {
      flex-direction: column;
    }

    .canvas-area {
      order: 1;
      padding: var(--spacing-md);
      min-height: 300px;
    }

    .sidebar {
      order: 2;
      width: 100%;
      max-width: none;
      min-width: 0;
      border-right: none;
      border-top: 1px solid rgba(255, 255, 255, 0.1);
      padding: var(--spacing-md);
      max-height: 40vh;
    }
  }

  @media (max-width: 600px) {
    .canvas-area {
      padding: var(--spacing-sm);
    }

    .sidebar {
      max-height: 50vh;
    }
  }

  /* Avatar mount point for lesson instructions */
  .avatar-mount {
    position: fixed;
    bottom: 20px;
    left: calc(33vw - 90px);
    width: 180px;
    height: 180px;
    z-index: 1000;
    pointer-events: none;
  }

  @media (max-width: 900px) {
    .avatar-mount {
      left: 20px;
      bottom: 20px;
      width: 120px;
      height: 120px;
    }
  }
</style>
